<?php
namespace App\Http\Controllers; use App\Models\{Benefit,SeniorCitizen}; use Illuminate\Http\Request;
class BenefitController extends Controller { public function index(Request $r){$q=Benefit::with('seniorCitizen');if($s=$r->get('search'))$q->whereHas('seniorCitizen',fn($w)=>$w->where('first_name','like',"%$s%")->orWhere('last_name','like',"%$s%"));if($st=$r->get('status'))$q->where('status',$st);return view('benefits.index',['benefits'=>$q->latest()->paginate(10)->withQueryString()]);} public function create(){return view('benefits.form',['benefit'=>new Benefit,'seniors'=>SeniorCitizen::where('status','Active')->orderBy('last_name')->get()]);} public function store(Request $r){Benefit::create($this->data($r));return redirect()->route('benefits.index')->with('success','Benefit record added.');} public function show(Benefit $benefit){return view('benefits.show',['benefit'=>$benefit->load('seniorCitizen')]);} public function edit(Benefit $benefit){return view('benefits.form',compact('benefit')+['seniors'=>SeniorCitizen::orderBy('last_name')->get()]);} public function update(Request $r,Benefit $benefit){$benefit->update($this->data($r));return redirect()->route('benefits.show',$benefit)->with('success','Benefit record updated.');} public function destroy(Benefit $benefit){$benefit->delete();return redirect()->route('benefits.index')->with('success','Benefit record deleted.');} private function data(Request $r){return $r->validate(['senior_citizen_id'=>'required|exists:senior_citizens,id','benefit_name'=>'required|string|max:150','benefit_type'=>'required|string|max:100','distribution_date'=>'nullable|date','status'=>'required|in:Scheduled,Distributed,Claimed,Unclaimed,Cancelled','reference_no'=>'nullable|string|max:100','notes'=>'nullable|string|max:2000']);} }
